import Foundation

struct Item: Identifiable, Codable, Hashable {
    let id: UUID
    /// Autogenerated, stable, human-readable code (e.g. "ITM-0001"). Assigned
    /// once by the repository on first save and never edited afterward.
    let code: String
    var name: String
    var itemDescription: String
    var imageData: Data?
    var sellPrice: Decimal
    var variants: [ItemVariant]
    let createdAt: Date

    init(
        id: UUID = UUID(),
        code: String,
        name: String,
        itemDescription: String = "",
        imageData: Data? = nil,
        sellPrice: Decimal = 0,
        variants: [ItemVariant] = [],
        createdAt: Date = Date()
    ) {
        self.id = id
        self.code = code
        self.name = name
        self.itemDescription = itemDescription
        self.imageData = imageData
        self.sellPrice = sellPrice
        self.variants = variants
        self.createdAt = createdAt
    }
}
